UserObject.mermaidData:
{
  "data": "classDiagram
    direction TB

    class User {
        +ObjectId _id
        +String name
        +String email {unique}
        +String password
        +Role role
        +Date createdAt
    }

    class Role {
        &lt;&lt;enumeration&gt;&gt;
        ADMIN
        OPERATOR
    }

    class RawMaterial {
        +ObjectId _id
        +String reference {unique}
        +String name
        +String unit
        +Number availableQuantity {&gt;= 0}
        +Number alertThreshold {&gt;= 0}
        +Date createdAt
    }

    class Product {
        +ObjectId _id
        +String reference {unique}
        +String name
        +Date createdAt
    }

    class CompositionItem {
        +ObjectId materialId
        +Number quantity {&gt; 0}
    }

    class ManufacturingOrder {
        +ObjectId _id
        +ObjectId productId
        +ObjectId assignedTo
        +Number targetQuantity {&gt; 0}
        +OrderStatus status
        +Date startedAt
        +Date endedAt
        +Date createdAt
    }

    class OrderSnapshotItem {
        +ObjectId materialId
        +String reference
        +String name
        +String unit
        +Number quantityPerUnit {&gt; 0}
    }

    class StockMovement {
        +ObjectId _id
        +ObjectId materialId
        +MovementType type
        +Number quantity {&gt; 0}
        +String reason
        +ObjectId orderId
        +ObjectId performedBy
        +Date createdAt
    }

    class OrderStatus {
        &lt;&lt;enumeration&gt;&gt;
        PLANIFIE
        EN_COURS
        TERMINE
        ANNULE
    }

    class MovementType {
        &lt;&lt;enumeration&gt;&gt;
        IN
        OUT
    }

    User "1" ..> "1" Role : possède

    Product "1" *-- "1..*" CompositionItem : composition
    CompositionItem "*" --> "1" RawMaterial : reference

    ManufacturingOrder "1" *-- "1..*" OrderSnapshotItem : snapshotComposition
    OrderSnapshotItem "*" --> "1" RawMaterial : reference_historique

    ManufacturingOrder "*" --> "1" Product : fabrique
    ManufacturingOrder "*" --> "1" User : assigné à (Opérateur)

    StockMovement "*" --> "1" RawMaterial : concerne
    StockMovement "*" --> "1" User : effectué par
    StockMovement "*" --> "0..1" ManufacturingOrder : lié à (Si type=OUT)",
  "config": null,
  "version": "12"
}
